///   %mask = vector.constant_mask [16]: vector<16xi1>
///   %val = xegpu.load %a[%offsets], %mask {l1_hint = #xegpu.cache_hint<cached>,
///                          l2_hint = #xegpu.cache_hint<cached>,
///                          l3_hint = #xegpu.cache_hint<cached>,
